PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE aggregate_stats (
  date TEXT NOT NULL,         -- 'YYYY-MM-DD' (UTC) or 'TOTAL'
  platform TEXT NOT NULL,     -- 'qqmusic' or 'all'
  metric TEXT NOT NULL,       -- 'parse_success', 'parse_failure'
  count INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (date, platform, metric)
);
CREATE TABLE daily_export_stats (
  date TEXT NOT NULL,                -- 'YYYY-MM-DD' (UTC) or 'TOTAL'
  platform TEXT NOT NULL,            -- 'qqmusic', 'all', etc.
  export_format TEXT NOT NULL,       -- 'txt', 'csv', 'xlsx', 'json',
                                     -- 'clipboard_title', 'clipboard_title_artist',
                                     -- 'clipboard_title_artist_album'
  count INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (date, platform, export_format)
);
CREATE TABLE hourly_stats (
  date TEXT NOT NULL,                -- 'YYYY-MM-DD' (UTC)
  hour INTEGER NOT NULL,             -- 0-23
  platform TEXT NOT NULL,            -- 'qqmusic', 'all'
  metric TEXT NOT NULL,              -- 'parse_success', 'parse_failure', 'rate_limited', 'export', 'clipboard'
  count INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (date, hour, platform, metric)
);
CREATE TABLE daily_client_stats (
  date TEXT NOT NULL,                -- 'YYYY-MM-DD' (UTC) or 'TOTAL'
  platform TEXT NOT NULL,            -- 'qqmusic', 'all'
  device_class TEXT NOT NULL,        -- 'desktop', 'mobile', 'tablet', 'unknown'
  browser_family TEXT NOT NULL,      -- 'chrome', 'firefox', 'safari', 'edge', 'other'
  os_family TEXT NOT NULL,           -- 'windows', 'macos', 'linux', 'android', 'ios', 'other'
  count INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (date, platform, device_class, browser_family, os_family)
);
CREATE TABLE daily_performance_stats (
  date TEXT NOT NULL,                -- 'YYYY-MM-DD' (UTC) or 'TOTAL'
  platform TEXT NOT NULL,            -- 'qqmusic', 'all'
  dimension TEXT NOT NULL,           -- 'input_type', 'playlist_size', 'latency_bucket', 'provider_path', 'error_category', 'rate_limit_endpoint'
  value TEXT NOT NULL,               -- e.g. 'web_url', '1-50', '<500ms', 'primary', 'error_upstream'
  count INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (date, platform, dimension, value)
);
CREATE TABLE daily_clipboard_stats (
  date TEXT NOT NULL,                -- 'YYYY-MM-DD' (UTC) or 'TOTAL'
  platform TEXT NOT NULL,            -- 'qqmusic', 'all'
  clipboard_mode TEXT NOT NULL,      -- 'title', 'title_artist', 'title_artist_album'
  count INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (date, platform, clipboard_mode)
);
CREATE TABLE daily_visitor_hashes (
  date TEXT NOT NULL,         -- 'YYYY-MM-DD' (UTC)
  hash TEXT NOT NULL,         -- truncated one-way SHA-256 hash (16 chars)
  PRIMARY KEY (date, hash)
);
CREATE TABLE IF NOT EXISTS "daily_geo_stats" (
  date TEXT NOT NULL,                -- 'YYYY-MM-DD' (UTC) or 'TOTAL'
  platform TEXT NOT NULL,            -- 'qqmusic', 'netease', 'all'
  country TEXT NOT NULL,             -- ISO 3166-1 alpha-2, e.g. 'CN', 'US', or 'UNKNOWN'
  region TEXT NOT NULL,              -- First-level subdivision / province, or 'UNKNOWN'
  city TEXT NOT NULL DEFAULT 'UNKNOWN', -- City name, or 'UNKNOWN'
  count INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (date, platform, country, region, city)
);
CREATE TABLE d1_migrations (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      name TEXT UNIQUE,
      applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    );
CREATE TABLE security_rate_limits (
  key TEXT NOT NULL PRIMARY KEY,   -- one-way hashed key: hash(scope, bucket, ip, salt)
  count INTEGER NOT NULL DEFAULT 1,
  reset_at INTEGER NOT NULL        -- unix timestamp in seconds
);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_stats_date_platform ON aggregate_stats (date, platform);
CREATE INDEX idx_export_stats_date ON daily_export_stats (date);
CREATE INDEX idx_hourly_stats_date ON hourly_stats (date);
CREATE INDEX idx_client_stats_date ON daily_client_stats (date);
CREATE INDEX idx_perf_stats_date ON daily_performance_stats (date);
CREATE INDEX idx_clipboard_stats_date ON daily_clipboard_stats (date);
CREATE INDEX idx_visitor_hashes_date ON daily_visitor_hashes (date);
CREATE INDEX idx_geo_stats_date ON daily_geo_stats (date);
CREATE INDEX idx_geo_stats_country ON daily_geo_stats (country, date);
CREATE INDEX idx_security_rate_limits_reset_at ON security_rate_limits (reset_at);
